import React, { useEffect, useState } from "react";
import { FaBars, FaTimes } from "react-icons/fa";
import Nav from './component/nav';
import api from '../api';
import Header from "./component/header";

const Pendaftar = () => {
  const [data, setData] = useState([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [user, setUser] = useState(null);

  const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);

  useEffect(() => {
    const fetchUser = async () => {
      try {
        const response = await api.get('/me');
        setUser(response.data.user);
      } catch (error) {
        console.error("Error fetching user:", error);
      }
    };
    fetchUser();
  }, []);

  return (
    <div className="flex flex-col h-screen bg-teal-100 font-sans">
      {/* Header */}
      <Header  isSidebarOpen={isSidebarOpen} setIsSidebarOpen={setIsSidebarOpen}/>

      {/* Container */}
      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <Nav isSidebarOpen={isSidebarOpen} />

        {/* Main Content */}
        <main className="flex-1 bg-teal-50 p-6 overflow-y-auto">
          <h2 className="text-4xl font-bold mb-4">Presensi</h2>
          <div className="overflow-x-auto">
          <table className="min-w-full bg-white border border-teal-300 rounded-lg shadow">
              <thead className="bg-teal-700 text-white">
                <tr>
                  <th className="px-6 py-3 text-left font-medium">NIM</th>
                  <th className="px-6 py-3 text-left font-medium">Nama</th>
                  <th className="px-6 py-3 text-left font-medium">Aksi</th>
                </tr>
              </thead>
              <tbody>
              {/* {data.length > 0 ? (
                data.map((row) => (
                  <tr key={row.id}>
                    <td className="px-6 py-4">{row.nim}</td>
                    <td className="px-6 py-4">{row.nama}</td>
                    <td className="px-6 py-4">{row.alamat}</td>

                  </tr>
                ))) : (
                  <tr>
                    <td
                      colSpan="7"
                      className="text-center px-6 py-4 text-gray-500"
                    >
                      Tidak ada jadwal tersedia.
                    </td>
                  </tr>
                )} */}
              </tbody>
            </table>
            <form id="form">
              <div>
                <div className="mb-4">
                  <label htmlFor="tanggal" className="block text-teal-800 font-medium mb-2">Tanggal</label>
                  <input
                    type="date"
                    id="tanggal"
                    className="w-full p-3 border border-teal-300 rounded-lg"
                    required
                  />
                </div>

                <div className="mb-4">
                  <label htmlFor="user_id" className="block text-teal-800 font-medium mb-2">User ID</label>
                  <input
                    type="number"
                    id="user_id"
                    value={ user.id}
                    className="w-full p-3 border border-teal-300 rounded-lg"
                    required
                  />
                </div>

                <div className="mb-4">
                  <label htmlFor="is_open" className="block text-teal-800 font-medium mb-2">Status Presensi</label>
                  <select
                    id="is_open"
                    className="w-full p-3 border border-teal-300 rounded-lg"
                    required
                  >
                    <option value="" disabled>Pilih status presensi</option>
                    <option value="false">Tutup</option>
                    <option value="true">Buka</option>
                  </select>
                </div>

                <div className="mb-4">
                  <label htmlFor="end_time" className="block text-teal-800 font-medium mb-2">Waktu Selesai (Menit)</label>
                  <select
                    id="end_time"
                    className="w-full p-3 border border-teal-300 rounded-lg"
                    required
                  >
                    <option value="" disabled>Pilih waktu selesai</option>
                    <option value="5">5 menit</option>
                    <option value="10">10 menit</option>
                    <option value="15">15 menit</option>
                  </select>
                </div>
              </div>

              <div className="text-center mt-6">
                <input
                  type="submit"
                  value="Buat Presensi"
                  className="w-full py-3 bg-teal-500 text-white rounded-lg cursor-pointer hover:bg-teal-600"
                />
              </div>
            </form>

          </div>
        </main>
      </div>
    </div>
  );
};

export default Pendaftar;
